Item.method_code:
/*
    帳票マスタ、開達書式共通の
    LCの改訂中から公開への遷移時の処理
    
    ・配下開達書式アンロックチェック：WFのメソッドから呼び出しているメソッドをこちらでも利用
    ・改訂履歴のアンロックチェック：WFのメソッドから呼び出しているメソッドをこちらでも利用
*/
Innovator inn = this.getInnovator();
string type = this.getType();
string id = this.getID();

// 帳票マスタの場合、配下開達書式チェック
if(type == "h4_DATMaster")
{
    using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
    {
        // 動作呼び出し
        Item callMethod1 = inn.newItem("Method", "h4_CheckIsLockRelatedDAT_Core");
        callMethod1.setID(id);
        callMethod1 = callMethod1.apply();
        if(callMethod1.isError())
        {
            //エラー
            return inn.newError(callMethod1.getErrorString());
        }  
    }
}

//共通動作 配下改訂履歴チェック
using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{
    // 動作呼び出し
    Item callMethod2 = inn.newItem("Method", "h4_CheckLockHist_Core");
    callMethod2.setID(id);
    callMethod2.setProperty("type",type);
    callMethod2 = callMethod2.apply();
    if(callMethod2.isError())
    {
        //エラー
        return inn.newError(callMethod2.getErrorString());
    } 
}

return this;
